{
  "project_id": "30a49407bdf14be3acda",
  "name": "create_distributed_application_locks",
  "query": "create schema if not exists app_lock;

create table if not exists app_lock.leases (
  lock_key text primary key,
  owner_token uuid not null,
  acquired_at timestamptz not null default now(),
  expires_at timestamptz not null,
  constraint leases_key_not_blank check (length(btrim(lock_key)) > 0),
  constraint leases_expiry_after_acquire check (expires_at >= acquired_at)
);

alter table app_lock.leases enable row level security;

create or replace function app_lock.acquire(
  p_lock_key text,
  p_lease_seconds integer default 30,
  p_owner_token uuid default null
)
returns uuid
language plpgsql
security invoker
set search_path = pg_catalog, app_lock
as $$
declare
  v_token uuid := coalesce(p_owner_token, gen_random_uuid());
  v_token uuid;
begin
  if p_lock_key is null or length(btrim(p_lock_key)) = 0 then
    raise exception using message = 'lock key must not be empty', errcode = '22023';
  end if;
  if p_lease_seconds < 1 or p_lease_seconds > 86400 then
    raise exception using message = 'lease must be between 1 and 86400 seconds', errcode = '22023';
  end if;

  insert into app_lock.leases(lock_key, owner_token, acquired_at, expires_at)
  values (p_lock_key, v_token, clock_timestamp(), clock_timestamp() + make_interval(secs => p_lease_seconds))
  on conflict (lock_key) do update
    set owner_token = excluded.owner_token,
        acquired_at = clock_timestamp(),
        expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds)
    where app_lock.leases.expires_at <= clock_timestamp()
       or (p_owner_token is not null and app_lock.leases.owner_token = p_owner_token)
  returning owner_token into v_token;

  return v_token;
end;
$$;

create or replace function app_lock.release(
  p_lock_key text,
  p_owner_token uuid
)
returns boolean
language sql
security invoker
set search_path = pg_catalog, app_lock
as $$
  delete from app_lock.leases
  where lock_key = p_lock_key and owner_token = p_owner_token
  returning true;
$$;

create or replace function app_lock.renew(
  p_lock_key text,
  p_owner_token uuid,
  p_lease_seconds integer default 30
)
returns boolean
language plpgsql
security invoker
set search_path = pg_catalog, app_lock
as $$
begin
  if p_lease_seconds < 1 or p_lease_seconds > 86400 then
    raise exception using message = 'lease must be between 1 and 86400 seconds', errcode = '22023';
  end if;
  update app_lock.leases
  set expires_at = clock_timestamp() + make_interval(secs => p_lease_seconds)
  where lock_key = p_lock_key
    and owner_token = p_owner_token
    and expires_at > clock_timestamp();
  return found;
end;
$$;

create or replace function app_lock.cleanup_expired()
returns integer
language sql
security invoker
set search_path = pg_catalog, app_lock
as $$
  with deleted as (
    delete from app_lock.leases
    where expires_at <= clock_timestamp()
    returning 1
  ) select count(*)::integer from deleted;
$$;

revoke all on schema app_lock from public;
revoke all on table app_lock.leases from public;
revoke all on all functions in schema app_lock from public;

comment on schema app_lock is 'Lease-based distributed application locks. Acquire returns an opaque owner token; release/renew require that token.';
comment on function app_lock.acquire(text, integer, uuid) is 'Atomically acquires or renews a lock. Returns a token, or NULL when another unexpired owner holds it.';
comment on function app_lock.release(text, uuid) is 'Releases only the lock owned by the supplied token.';
comment on function app_lock.renew(text, uuid, integer) is 'Extends an unexpired lock owned by the supplied token.';
"
}

